//! What this build calls itself: the banner Reva prints at startup, and the
//! fuller report shared by `reva -V` and the Forth word `version`.
//!
//! The version is the workspace's `major.minor` (`2026.10` for 2026.10.0);
//! the build details come from `build.rs`.  `revaver` still answers
//! `2011.2`, the release of `reva.f` this core runs, since libraries test it.

/// The fork's name.
pub const NAME: &str = "reva-fork";

/// `major.minor` of the workspace version.
pub const VERSION: &str = concat!(
