//! Web UI detection

use std::path::Path;

/// Check if a crate appears to be a Web UI (not just server-side WASM)
pub fn is_web_ui_crate(crate_dir: &Path) -> bool {
    let has_index = crate_dir.join("index.html").exists();
    let has_trunk = crate_dir.join("Trunk.toml").exists();
    let has_static = ["static", "public", "dist", "assets", "www"]
        .iter()
        .any(|d| crate_dir.join(d).exists());
    has_index || has_trunk || has_static
}
//! Build metadata checking for Web UI crates

use checklist_result::CheckResult;
use wasm_html::collect_source_content;
use std::path::Path;

/// Check for footer presence and build metadata
pub fn check_web_ui_metadata(crate_dir: &Path, crate_name: &str) -> Vec<CheckResult> {
    let label = format!("[{}]", crate_name);

    if !crate_dir.join("src").exists() {
        return vec![CheckResult::warn(
            format!("Web UI Metadata {}", label),
            "No src/ directory",
        )];
    }

    let (source, found_footer) = collect_source_content(crate_dir);
    let lower = source.to_lowercase();

    let mut results = vec![check_footer(&label, found_footer, &lower)];
    results.extend(check_fields(&label, &lower));
    results
}

fn check_footer(label: &str, found: bool, lower: &str) -> CheckResult {
    if found {
        CheckResult::pass(format!("Footer Presence {}", label), "Found footer element")
    } else if lower.contains("footer") {
        CheckResult::warn(
            format!("Footer Presence {}", label),
            "Found 'footer' but no element",
        )
    } else {
        CheckResult::warn(
            format!("Footer Presence {}", label),
            "No footer element found",
        )
    }
}

fn check_fields(label: &str, content: &str) -> Vec<CheckResult> {
    vec![
        check_field(label, "Copyright", content, &["copyright"]),
        check_field(label, "License", content, &["license"]),
        check_field(
            label,
            "Repository",
            content,
            &["github.com", "gitlab.com", "repository"],
        ),
        check_field(label, "Build Host", content, &["build_host", "build host"]),
        check_field(label, "Build Commit", content, &["build_commit", "commit"]),
        check_field(label, "Build Time", content, &["build_time", "timestamp"]),
    ]
}

fn check_field(label: &str, name: &str, content: &str, patterns: &[&str]) -> CheckResult {
    if patterns.iter().any(|p| content.contains(p)) {
        CheckResult::pass(format!("{} {}", name, label), format!("Found {}", name))
    } else {
        CheckResult::warn(format!("{} {}", name, label), format!("No {} found", name))
    }
}
//! Source content collection for Web UI crates

use std::fs;
use std::path::Path;
use walkdir::WalkDir;

/// Collect all source content and check for footer patterns
pub fn collect_source_content(crate_dir: &Path) -> (String, bool) {
    let (rs_content, found_rs) = collect_rs_files(crate_dir);
    let (html_content, found_html) = collect_index_html(crate_dir);

    let mut all = rs_content;
    all.push_str(&html_content);
    (all, found_rs || found_html)
}

fn collect_rs_files(crate_dir: &Path) -> (String, bool) {
    let mut content = String::new();
    let mut found = false;

    for entry in WalkDir::new(crate_dir.join("src"))
        .into_iter()
        .filter_map(|e| e.ok())
        .filter(|e| e.path().extension().and_then(|s| s.to_str()) == Some("rs"))
    {
        if let Ok(file) = fs::read_to_string(entry.path()) {
            if has_footer(&file) {
                found = true;
            }
            content.push_str(&file);
            content.push('\n');
        }
    }
    (content, found)
}

fn collect_index_html(crate_dir: &Path) -> (String, bool) {
    if let Ok(html) = fs::read_to_string(crate_dir.join("index.html")) {
        let found = html.to_lowercase().contains("<footer");
        (html, found)
    } else {
        (String::new(), false)
    }
}

fn has_footer(content: &str) -> bool {
    let lower = content.to_lowercase();
    lower.contains("<footer")
        || lower.contains("class=\"footer\"")
        || (lower.contains("fn footer") && lower.contains("html!"))
}
