    onUi: (m) => { if (m.channel === "canvas") canvas.handle(m); },
    onStatus: (s) => {
      stop.disabled = s !== RUNNING;
      if (s === HALTED) {
        echo(`\n[exited with status ${reva.exitCode}]\n`);
        line.disabled = true;
        halted(reva.exitCode);
      }
    },
  });
  // Turtle graphics go to their own window (ui.js), or a pane; once used,
  // the Graphics button brings a closed one back.  The split view shows
  // its pane from the start.
  canvas = new CanvasChannel(host, reva, {
    where: mode === "window" ? "window" : "pane",
    onState: (s) => {
      if (split) return;
      gfx.hidden = false;
      gfx.textContent = s === "closed" ? "Graphics (closed)" : "Graphics";
    },
  });
  if (split) canvas.open();
  gfx.addEventListener("click", () => {
    if (canvas.win && !canvas.win.closed()) canvas.win.focus();
    else canvas.open();
  });
  // Batch runs (the desktop's --print-output) report what the graphics
  // window drew, after giving it a moment to finish.
  async function halted(code) {
    if (canvas.used && host.output) {
      for (let i = 0; i < 40 && canvas.lines === 0; i++) await new Promise((r) => setTimeout(r, 50));
      host.output(`[canvas: ${canvas.lines} lines]\n`);
    }
    host.halted?.(code);
  }
  const starting = append("starting...\n", "echo");
  for (const n of notes) append(`note: ${n}\n`, "echo");
  await reva.ready;
  starting.remove();
  // Start lines (a package's start files) are read again after `restart`;
  // input lines only once.
  for (const text of [...(pkg?.start ?? []), ...(host.start ?? [])]) {
    echo(text + "\n");
    reva.feedStart(text + "\n");
  }
  for (const text of host.input ?? []) {
    echo(text + "\n");
    reva.feed(text + "\n");
  }

  // Lines typed while the page was still starting go in after the start lines.
  feedLine = (text) => reva.feed(text + "\n");
  for (const text of early.splice(0)) feedLine(text);
  stop.addEventListener("click", () => reva.stop());
  document.addEventListener("keydown", (e) => {
    if (e.ctrlKey && e.key === "c" && !window.getSelection()?.toString()) {
      e.preventDefault();
      reva.stop();
    }
  });
</script>
</body>
</html>

